			for (int mask = 1; mask <= FrontierLeafProbe.ALL_COMPONENTS; mask++) {
				int shardId = COUNT_MIN_SHARD_BASE + plane * FrontierLeafProbe.ALL_COMPONENTS + mask - 1;
				long logicalKey = logicalKey(plane, mask);
				long[] counters = matrix.copyCounters(plane, mask);
				FrontierStatisticsShardDescriptor descriptor = writeShard(directory, generationId, shardId, epoch,
						maximumTermId, counters.length, FrontierStatisticsTier.EXACT_AND_LINEAR,
						FrontierStatisticsShardKind.COUNT_MIN, logicalKey, config.countMinDepth(),
						writer -> writer.addUnsignedColumn(0, counters), fileOps);
				budgets.add(descriptor);
				descriptors.add(descriptor);
			}
